BEGIN; DO $$ BEGIN IF to_regprocedure('public.is_admin()') IS NULL OR to_regprocedure('public.is_manager()') IS NULL THEN RAISE EXCEPTION 'Thieu ham kiem tra quyen is_admin/is_manager. Dung lai de kiem tra schema.'; END IF; END $$; CREATE OR REPLACE FUNCTION public.save_inventory_stocktake_draft_v1(p_header_id uuid,p_stocktake_date date,p_note text,p_lines jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_user_id uuid:=auth.uid(); v_now timestamptz:=now(); v_status text; v_input_count integer:=0; v_inserted_count integer:=0; BEGIN IF v_user_id IS NULL OR NOT public.is_manager() THEN RAISE EXCEPTION 'Ban khong co quyen luu nhap kiem ke.' USING ERRCODE='42501'; END IF; IF p_header_id IS NULL OR p_stocktake_date IS NULL OR p_lines IS NULL OR jsonb_typeof(p_lines)<>'array' THEN RAISE EXCEPTION 'Du lieu phieu kiem ke khong hop le.'; END IF; SELECT st.status INTO v_status FROM public.inventory_stocktakes st WHERE st.id=p_header_id AND st.deleted_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Khong tim thay phieu kiem ke.'; END IF; IF v_status<>'draft' THEN RAISE EXCEPTION 'Phieu da chot, khong the luu theo luong ban nhap.'; END IF; IF EXISTS(SELECT 1 FROM public.inventory_transactions t WHERE t.stocktake_id=p_header_id AND t.deleted_at IS NULL) OR EXISTS(SELECT 1 FROM public.inventory_opening_balances ob WHERE ob.source_stocktake_id=p_header_id AND ob.deleted_at IS NULL) THEN RAISE EXCEPTION 'Ban nhap dang co anh huong den ton kho. Dung lai de kiem tra, khong du lieu nao thay doi.'; END IF; CREATE TEMP TABLE stocktake_draft_input ON COMMIT DROP AS SELECT e.line_no,NULLIF(e.line->>'product_id','')::uuid AS product_id,COALESCE(NULLIF(e.line->>'system_qty_before','')::numeric,0) AS system_qty_before,COALESCE(NULLIF(e.line->>'actual_qty_after','')::numeric,0) AS actual_qty_after,NULLIF(e.line->>'diff_reason','') AS diff_reason FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS e(line,line_no); SELECT count(*) INTO v_input_count FROM pg_temp.stocktake_draft_input; IF EXISTS(SELECT 1 FROM pg_temp.stocktake_draft_input WHERE product_id IS NULL) THEN RAISE EXCEPTION 'Co dong kiem ke chua chon ma hang.'; END IF; IF EXISTS(SELECT 1 FROM pg_temp.stocktake_draft_input WHERE actual_qty_after<0) THEN RAISE EXCEPTION 'So dem thuc te khong duoc am.'; END IF; IF EXISTS(SELECT 1 FROM pg_temp.stocktake_draft_input GROUP BY product_id HAVING count(*)>1) THEN RAISE EXCEPTION 'Mot ma hang chi duoc xuat hien mot dong trong phieu kiem ke.'; END IF; IF EXISTS(SELECT 1 FROM pg_temp.stocktake_draft_input i LEFT JOIN public.products p ON p.id=i.product_id AND p.deleted_at IS NULL WHERE p.id IS NULL) THEN RAISE EXCEPTION 'Co ma hang khong ton tai hoac da bi huy.'; END IF; UPDATE public.inventory_stocktakes SET stocktake_date=p_stocktake_date,note=p_note,updated_at=v_now,updated_by=v_user_id WHERE id=p_header_id AND status='draft' AND deleted_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Phieu vua thay doi trang thai. Tai lai trang va thu lai.'; END IF; UPDATE public.inventory_stocktake_lines SET deleted_at=v_now,deleted_by=v_user_id,updated_at=v_now,updated_by=v_user_id WHERE stocktake_id=p_header_id AND deleted_at IS NULL; INSERT INTO public.inventory_stocktake_lines(stocktake_id,product_id,customer_id,product_name_snapshot,product_spec_snapshot,unit_price_snapshot,system_qty_before,actual_qty_after,qty_diff,diff_percent,is_large_diff,diff_reason,created_by,updated_by) SELECT p_header_id,i.product_id,NULL,p.name,p.spec,p.unit_price,i.system_qty_before,i.actual_qty_after,i.actual_qty_after-i.system_qty_before,CASE WHEN i.system_qty_before=0 THEN CASE WHEN i.actual_qty_after=0 THEN 0 ELSE 100 END ELSE abs(i.actual_qty_after-i.system_qty_before)/abs(i.system_qty_before)*100 END,CASE WHEN i.system_qty_before=0 THEN i.actual_qty_after<>0 ELSE abs(i.actual_qty_after-i.system_qty_before)/abs(i.system_qty_before)*100>10 END,i.diff_reason,v_user_id,v_user_id FROM pg_temp.stocktake_draft_input i JOIN public.products p ON p.id=i.product_id AND p.deleted_at IS NULL ORDER BY i.line_no; GET DIAGNOSTICS v_inserted_count=ROW_COUNT; IF v_inserted_count<>v_input_count THEN RAISE EXCEPTION 'Khong luu du cac dong kiem ke. Toan bo thao tac duoc hoan tac.'; END IF; RETURN jsonb_build_object('success',true,'saved_line_count',v_inserted_count,'message','Da luu ban nhap kiem ke tron ven.'); END $$; CREATE OR REPLACE FUNCTION public.cancel_inventory_stocktake_draft_v1(p_stocktake_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_user_id uuid:=auth.uid(); v_now timestamptz:=now(); v_status text; v_line_count integer:=0; v_header_count integer:=0; BEGIN IF v_user_id IS NULL OR NOT public.is_admin() THEN RAISE EXCEPTION 'Chi Admin hoac Super Admin duoc huy ban nhap kiem ke.' USING ERRCODE='42501'; END IF; IF p_stocktake_id IS NULL THEN RAISE EXCEPTION 'Thieu ma phieu kiem ke.'; END IF; SELECT st.status INTO v_status FROM public.inventory_stocktakes st WHERE st.id=p_stocktake_id AND st.deleted_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Khong tim thay phieu kiem ke hoac phieu da duoc huy.'; END IF; IF v_status<>'draft' THEN RAISE EXCEPTION 'Chi duoc huy phieu o trang thai ban nhap. Phieu da chot khong thay doi.'; END IF; IF EXISTS(SELECT 1 FROM public.inventory_transactions t WHERE t.stocktake_id=p_stocktake_id AND t.deleted_at IS NULL) OR EXISTS(SELECT 1 FROM public.inventory_opening_balances ob WHERE ob.source_stocktake_id=p_stocktake_id AND ob.deleted_at IS NULL) THEN RAISE EXCEPTION 'Ban nhap dang co anh huong den ton kho. Dung lai de kiem tra, khong du lieu nao thay doi.'; END IF; UPDATE public.inventory_stocktake_lines SET deleted_at=v_now,deleted_by=v_user_id,updated_at=v_now,updated_by=v_user_id WHERE stocktake_id=p_stocktake_id AND deleted_at IS NULL; GET DIAGNOSTICS v_line_count=ROW_COUNT; UPDATE public.inventory_stocktakes SET deleted_at=v_now,deleted_by=v_user_id,updated_at=v_now,updated_by=v_user_id WHERE id=p_stocktake_id AND status='draft' AND deleted_at IS NULL; GET DIAGNOSTICS v_header_count=ROW_COUNT; IF v_header_count<>1 THEN RAISE EXCEPTION 'Khong huy duoc dau phieu. Toan bo thao tac duoc hoan tac.'; END IF; RETURN jsonb_build_object('success',true,'cancelled_line_count',v_line_count,'message','Da huy mem ban nhap kiem ke. Ton kho khong thay doi.'); END $$; REVOKE ALL ON FUNCTION public.save_inventory_stocktake_draft_v1(uuid,date,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.save_inventory_stocktake_draft_v1(uuid,date,text,jsonb) TO authenticated; REVOKE ALL ON FUNCTION public.cancel_inventory_stocktake_draft_v1(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cancel_inventory_stocktake_draft_v1(uuid) TO authenticated; NOTIFY pgrst,'reload schema'; COMMIT;
